@spec editor_verbs_spec  src=tests/specs/editor_verbs_spec.lua  loc=118  sha=untracked  cases=4
@exercises swingEditor (se), configManager (h.cm)
@surface   se:open, se:libraryDescriptor, cm:getAt
@harness   mk

# Intent
  Verb descriptors on the swing/temper editors under the library model:
  `publish` lifts a project copy into the shared library, `revert` discards
  project drift back to its source, and `tidy` (swing only) drops pristine
  unreferenced project copies. Instantiated over a harness cm/ds with a lib
  service; imgui stubbed via package.preload. Recipe lifted from
  temperEditor_tree_spec.

# Helpers
  @fn mkLib(h)  @ 19-24
  @fn facadeStub()  @ 28-37
      -- Swing reaches the arrange/tracker services only for the reference scan and
      -- default-slot resolution; a leaf on each covers the descriptor path.
  @fn mkSwing(h)  @ 39-49
  @fn mkTemper(h)  @ 51-58

# Cases
  @case 'swing onPublish lifts a project copy into the library tier'  [harness]  @ 62-73
  @case 'swing onRevert restores a divergent project copy from its source'  [harness]  @ 76-89
  @case 'swing descriptor exposes onTidy; temper omits it'  [harness]  @ 92-100
  @case 'swing onTidy drops a pristine unreferenced copy, keeps a divergent one'  [harness]  @ 103-116

# Uses (outbound edges)
